SELECT *
FROM shopion.tOrdSlnkTrans



            AND MallCode = ''
            AND MallCode = #{pMallCode}


    AND TransType = #{pTransType}

        AND (TransStartDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND TransStartDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY))



    ORDER BY ${sidx} ${sord}
    ORDER BY TransId DESC
